// Router inteligente para webhooks encadenados
// Backwards compatible con el workflow simple (echo)

const body = $input.first().json.body || $input.first().json;
const payload = body.payload || body;
const action = payload.action || payload._action || '';

// ── Ruta 1: buscar_cliente ─────────────────────────────────────────
if (action === 'buscar_cliente') {
  const rut = payload.rut || payload.documento || '11.111.111-1';
  return [{ json: {
    ok: true,
    action: 'cliente_encontrado',
    cliente_id: 'CL_' + Math.random().toString(36).slice(2, 8).toUpperCase(),
    rut,
    nombre: 'Juan Pérez',
    plan: 'premium',
    estado: 'activo',
    saldo_disponible_clp: 1500000,
    note: 'Mock data — usa cliente_id para llamar a enviar_oferta'
  }}];
}

// ── Ruta 2: enviar_oferta (requiere cliente_id de la llamada anterior) ──
if (action === 'enviar_oferta') {
  const { cliente_id, plan } = payload;
  if (!cliente_id) {
    return [{ json: {
      ok: false,
      error: 'Falta cliente_id. Llama primero a buscar_cliente para obtenerlo.'
    }}];
  }
  return [{ json: {
    ok: true,
    action: 'oferta_enviada',
    oferta_id: 'OF_' + Math.random().toString(36).slice(2, 8).toUpperCase(),
    cliente_id,
    plan: plan || 'standard',
    descuento_clp: plan === 'premium' ? 25000 : 10000,
    moneda: 'CLP',
    valida_hasta: '2026-06-30',
    canal: 'WhatsApp + Email',
    note: 'Mock data — oferta enviada al cliente ' + cliente_id
  }}];
}

// ── Ruta 3: cobrar (tercer eslabón opcional para chains más largos) ──
if (action === 'cobrar') {
  const { oferta_id } = payload;
  if (!oferta_id) {
    return [{ json: { ok: false, error: 'Falta oferta_id de enviar_oferta.' }}];
  }
  return [{ json: {
    ok: true,
    action: 'cobro_realizado',
    transaccion_id: 'TX_' + Math.random().toString(36).slice(2, 10).toUpperCase(),
    oferta_id,
    monto_cobrado_clp: 25000,
    estado: 'completado',
    timestamp: new Date().toISOString()
  }}];
}

// ── Default: echo (compat con el workflow original) ──
const webhookName = body.webhookName || 'desconocido';
return [{ json: {
  ok: true,
  receivedAt: new Date().toISOString(),
  webhookName,
  summary: `n8n recibió webhook "${webhookName}" con ${Object.keys(payload).length} campo(s).`,
  payloadEcho: payload,
  note: 'Echo default. Para chain demo incluye payload.action: "buscar_cliente", "enviar_oferta" o "cobrar".'
}}];
